style.css:
@-moz-document domain("discord.com") {
/* Background Image */
   body {
      background-image: url("https://i.pinimg.com/564x/21/75/e3/2175e3005a3d53f6315a7926c363e7ef.jpg") !important;
      background-size: cover !important;
      background-position: center !important;
      background-attachment: fixed !important;
      background-repeat: no-repeat !important;
      position: relative !important;
   }

   /* Overlay for Subtle Tint */
   body::before {
      content: "";
      position: fixed;
      top: 0;
      left: 0;
      width: 100%;
      height: 100%;
      background-color: rgba(139, 69, 19, 0.3); /* Light brown tint overlay */
      pointer-events: none;
      z-index: -1;
   }

   /* Text and UI Colors */
   .container, .text, .message {
      color: #FAF0E6 !important; /* Light brownish tone for readable text */
   }

   /* Accent and Button Colors */
   .button {
      background-color: #8B0000 !important; /* Dark red for button backgrounds */
      color: #000000 !important; /* Black text on buttons */
   }

   /* Border and Card Backgrounds */
   .border, .card {
      border-color: #8B4513 !important; /* Light brown for borders */
      background-color: rgba(245, 222, 179, 0.1) !important; /* Light cream with transparency for subtle accents */
   }

   /* Additional Black Accents */
   .username, .header {
      color: #000000 !important; /* Black text for headers and usernames */
   }
}
